import { create } from "zustand";

type IUser = {
  _id: string;
  name?: string;
  inviteUser?: [string];
  profilePicUrl?: string;
  phone?: string;
  password?: string;
  payment_password?: string;
  realBalance?: number;
  vip?: number;
  inviteCode?: string;
  refCode: string;
  roles: any;
  verified?: boolean;
  status?: boolean;
  createdAt?: Date;
  updatedAt?: Date;
};

export type AuthState = {
  user: IUser | null;
  logged: boolean;
};

export type AuthActions = {
  onSetUser: (val: IUser) => void;
};

export const useAuthApp = create<AuthState & AuthActions>((set) => ({
  user: null,
  logged: JSON.parse(localStorage.getItem("logged") as string ),
  onSetUser: (user: any) => {
    set((state) => {
      state.user = user;
      state.logged = true;
      localStorage.setItem("logged", "1");
      return { ...state };
    });
  },
}));
